INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6e7b987ecc9507462bbf','AMEDEX 2025 CVS (2).pdf','81','Cardiology','POTS, also known as postural autonomic
tachycardia, or chronic or idiopathic orthostatic
intolerance is a syndrome of orthostatic
intolerance in younger patients. Various
symptoms (e.g. fatigue, lignt-headedness,
exercise intolerance, cognitive impairment) and
tachycardia occur with standing; however, there
is little or no fall in BP. The reason for symptoms
is unclear.
Table tilt test:
This test may be done when autonomic
dysfunction is suspected. It gives more
consistent results than supine and upright blood
pressure assessment and eliminates
augmentation of venous return by leg muscle
contraction.
What is table tilt test and how it is interpreted?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","supporting_pages":[81],"source_qid":null,"duplicate_group_id":"exact-60e72f31810a","duplicate_sources":[{"record_id":"6e7b987ecc9507462bbf","record_type":"visual_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_page":81,"source_qid":null}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/AMEDEX_2025_CVS_2__2f0ae2272893/page_00081.jpg","asset_preview_url":"https://drive.google.com/file/d/1jrMUuUWn4lyNTc9iSPMnIRE2VgPNC954/preview"}','visual_assets/AMEDEX_2025_CVS_2__2f0ae2272893/page_00081.jpg','https://drive.google.com/thumbnail?id=1jrMUuUWn4lyNTc9iSPMnIRE2VgPNC954&sz=w1600','source_page_image',NULL,'needs_verification','[]','low','{"record_id":"6e7b987ecc9507462bbf","record_type":"visual_mcq","source_file":"AMEDEX 2025 CVS (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 CVS (2).pdf","source_year":2025,"source_page":81,"supporting_pages":[81],"source_qid":null,"domain_hint":"Cardiology","stem":"POTS, also known as postural autonomic\ntachycardia, or chronic or idiopathic orthostatic\nintolerance is a syndrome of orthostatic\nintolerance in younger patients. Various\nsymptoms (e.g. fatigue, lignt-headedness,\nexercise intolerance, cognitive impairment) and\ntachycardia occur with standing; however, there\nis little or no fall in BP. The reason for symptoms\nis unclear.\nTable tilt test:\nThis test may be done when autonomic\ndysfunction is suspected. It gives more\nconsistent results than supine and upright blood\npressure assessment and eliminates\naugmentation of venous return by leg muscle\ncontraction.\nWhat is table tilt test and how it is interpreted?","options":null,"options_mode":"source_page_image