INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7a068e557cf80e5ded4d','AMEDEX 2025 Emergency Medicine 1.pdf','32','Emergency Medicine','John, 15 years of age, is a patient of yours
since he was born. Today, his mother has
brought him to your office after his left
hand was bitten by his dog. The
bite happened when John accidentally
stepped on the dog''s tail and provoked the
animal. On examination, there is a puncture
wound which slightly bleeds when you remove
the bandage the mother put on at home. No
associated bone or tendon injury is found. You
check his for his immunization status and
know that his primary and booster vaccines (a
total of 5 doses) has been given with the last
booster at the age of 4 years. You debride the
wound, disinfect it, and put a non-adherent
absorbent plaster as covering. You also
prescribe a 5-day course of co-amoxiclave for
prevention of infections. Since it is a deep bite
wound, you decide to also be on the safe side
and give him prophylaxis against tetanus.
Which one of the following would be the best
course of action for tetanus prophylaxis for him’?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Emergency Medicine 1.pdf","supporting_pages":[32],"source_qid":null,"duplicate_group_id":"exact-f51fd29629a3","duplicate_sources":[{"record_id":"7a068e557cf80e5ded4d","record_type":"visual_mcq","source_file":"AMEDEX 2025 Emergency Medicine 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Emergency Medicine 1.pdf","source_page":32,"source_qid":null},{"record_id":"e64ddc204272aab0aff8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":286,"source_qid":null}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/AMEDEX_2025_Emergency_Medicine_1__6020909e0743/page_00032.jpg","asset_preview_url":"https://drive.google.com/file/d/1Te_F1PJfo4GTRzbh-ccYHZ9LiHHIVFTP/preview"}','visual_assets/AMEDEX_2025_Emergency_Medicine_1__6020909e0743/page_00032.jpg','https://drive.google.com/thumbnail?id=1Te_F1PJfo4GTRzbh-ccYHZ9LiHHIVFTP&sz=w1600','source_page_image',NULL,'needs_verification','[]','high','{"record_id":"7a068e557cf80e5ded4d","record_type":"visual_mcq","source_file":"AMEDEX 2025 Emergency Medicine 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Emergency Medicine 1.pdf","source_year":2025,"source_page":32,"supporting_pages":[32],"source_qid":null,"domain_hint":"Emergency Medicine","stem":"John, 15 years of age, is a patient of yours\nsince he was born. Today, his mother has\nbrought him to your office after his left\nhand was bitten by his dog. The\nbite happened when John accidentally\nstepped on the dog''s tail and provoked the\nanimal. On examination, there is a puncture\nwound which slightly bleeds when you remove\nthe bandage the mother put on at home. No\nassociated bone or tendon injury is fo